<div class="col-md-4"><label>Surname</label><input class="form-control" name="surname" required></div><div class="col-md-4"><label>First name</label><input class="form-control" name="firstname" required></div><div class="col-md-4"><label>Other name</label><input class="form-control" name="othername"></div><div class="col-md-4"><label>Gender</label><select class="form-select" name="gender"><option value="">Select</option><option>Male</option><option>Female</option><option>Other</option></select></div><div class="col-md-4"><label>Date of birth</label><input class="form-control" type="date" name="dob"></div><div class="col-md-4"><label>Class applying for</label><input class="form-control" name="applying_class"></div>
